// Open Sign Language: a read-only view of data/*.json (generated by scripts/parse.py).
// No dependencies. All text from the data goes through textContent, never innerHTML.

const UPSTREAM = 'https://github.com/Ginqwerty/Open-Sign-Language';
const BRANCH = 'main';
const DATA = '../data/';
const VIEWS = ['papers', 'datasets', 'leaderboards'];

// ---------------------------------------------------------------- small helpers
function el(tag, props = {}, ...kids) {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(props)) {
    if (v == null || v === false) continue;
    if (k === 'class') n.className = v;
    else if (k === 'text') n.textContent = v;
    else if (k.startsWith('on')) n.addEventListener(k.slice(2), v);
    else n.setAttribute(k, v === true ? '' : v);
  }
  for (const kid of kids.flat()) {
    if (kid != null && kid !== false) n.append(kid.nodeType ? kid : document.createTextNode(String(kid)));
  }
  return n;
}

// Only http(s) links are ever rendered as links. A link written without a scheme
// in the source (for example "github.com/user/repo") is opened with https://.
function safeUrl(u) {
  if (!u) return null;
  let s = String(u).trim();
  if (!/^[a-z][a-z0-9+.-]*:/i.test(s)) s = 'https://' + s;
  try {
    const url = new URL(s);
    return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : null;
  } catch { return null; }
}
function link(text, url, props = {}) {
  const href = safeUrl(url);
  if (!href) return el('span', { text });
  return el('a', { href, rel: 'noopener noreferrer', ...props, text });
}
const srcUrl = (file, line) => `${UPSTREAM}/blob/${BRANCH}/${file}#L${line}`;

const MISSING = new Set(['', '-', '\\-', 'n/a', 'unknown', 'none', '?']);
const isMissing = (v) => MISSING.has(String(v ?? '').trim().toLowerCase());
const dash = () => el('span', { class: 'dash', 'aria-label': 'not given', text: '–' });
const addUnique = (arr, v) => { if (v != null && v !== '' && !arr.includes(v)) arr.push(v); };
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const num = (s) => { const m = String(s ?? '').match(/\d{4}/); return m ? Number(m[0]) : null; };

// ---------------------------------------------------------------- state in the URL hash
let view = 'papers';
let params = new URLSearchParams();
function readHash() {
  const [v, qs = ''] = location.hash.slice(1).split('?');
  view = VIEWS.includes(v) ? v : 'papers';
  params = new URLSearchParams(qs);
}
function setParam(key, value) {
  if (value == null || value === '') params.delete(key); else params.set(key, value);
  const qs = params.toString();
  history.replaceState(null, '', `#${view}${qs ? '?' + qs : ''}`);
}
const getParam = (k) => params.get(k) || '';

// ---------------------------------------------------------------- shared widgets
function field(label, id, control) {
  return el('div', { class: 'field' }, el('label', { for: id, text: label }), control);
}
function selectField(label, id, options, current, onChange) {
  const sel = el('select', { id });
  sel.append(el('option', { value: '', text: options.all }));
  for (const o of options.items) sel.append(el('option', { value: o.value, text: o.label }));
  sel.value = options.items.some((o) => o.value === current) ? current : '';
  sel.addEventListener('change', () => onChange(sel.value));
  return field(label, id, sel);
}
function searchField(label, id, placeholder, current, onChange) {
  const input = el('input', { id, type: 'search', placeholder, value: current, autocomplete: 'off' });
  input.addEventListener('input', () => onChange(input.value));
  return field(label, id, input);
}

// Year buttons: the bar heights show how many records match the other filters;
// a click filters by that year.
function yearStrip(buckets, selected, noun, onPick) {
  const max = Math.max(1, ...buckets.map((b) => b.count));
  const maxLabels = window.innerWidth < 640 ? 6 : 16;
  const step = Math.max(1, Math.ceil(buckets.length / maxLabels));
  const wrap = el('div', { class: 'years', role: 'group', 'aria-label': `Filter ${noun} by year` });
  buckets.forEach((b, i) => {
    const show = i % step === 0 || i === buckets.length - 1;
    const pressed = String(selected) === String(b.value);
    wrap.append(el('button', {
      type: 'button', 'aria-pressed': String(pressed), disabled: b.count === 0 && !pressed,
      'aria-label': `${b.label}: ${plural(b.count, noun.replace(/s$/, ''), noun)}`,
      onclick: () => onPick(pressed ? '' : String(b.value)),
    },
    el('span', { class: 'n', text: b.count ? String(b.count) : '' }),
    el('span', { class: 'bar', style: `height:${Math.max(2, Math.round((b.count / max) * 70))}%` }),
    el('span', { class: 'y', text: show ? b.label : ' ' })));
  });
  return wrap;
}

function summaryLine(parts, shown, total, noun, hasFilters, clear) {
  const line = el('p', { class: 'summary', role: 'status' },
    el('span', {}, 'Showing ', el('strong', { text: String(shown) }), ` of ${total} ${noun}`), ...parts);
  if (hasFilters) line.append(el('button', { type: 'button', class: 'link', onclick: clear, text: 'Clear filters' }));
  return line;
}

// ---------------------------------------------------------------- papers
const TOPICS = ['Recognition', 'Translation', 'Production', 'Annotation and evaluation', 'Datasets', 'Other'];
const TOPIC_CLASS = { Recognition: 'rec', Translation: 'trans', Production: 'prod' };

// Topic is inferred from the README heading the entry sits under.
function topicOf(section) {
  const test = (s) => {
    const t = s.toLowerCase();
    if (/dataset/.test(t)) return 'Datasets';
    if (/\bslr\b/.test(t)) return 'Recognition';
    if (/\bslt\b|gloss/.test(t)) return 'Translation';
    if (/\bslp\b|slvg|skeleton|pose|video generation/.test(t)) return 'Production';
    if (/annotation|evaluation/.test(t)) return 'Annotation and evaluation';
    return null;
  };
  for (let i = section.length - 1; i >= 0; i--) { const r = test(section[i]); if (r) return r; }
  return 'Other';
}

function buildPapers(rows) {
  const map = new Map();
  for (const p of rows) {
    const key = p.key || `line${p.source.line}`;
    let g = map.get(key);
    if (!g) {
      g = { key, title: p.title, short: '', venues: [], years: [], kinds: [], sections: [], links: [], lines: [], earlier: false, survey: false };
      map.set(key, g);
    }
    if (!g.short && p.short_name) g.short = p.short_name;
    addUnique(g.venues, p.venue);
    if (p.year) addUnique(g.years, p.year);
    addUnique(g.kinds, p.kind);
    const label = p.section[p.section.length - 1] || '';
    if (!g.sections.some((s) => s.label === label)) g.sections.push({ label, topic: topicOf(p.section) });
    for (const l of p.links) if (!g.links.some((x) => x.url === l.url)) g.links.push(l);
    g.lines.push(p.source.line);
    g.earlier = g.earlier || p.earlier;
    g.survey = g.survey || p.section.some((s) => /survey/i.test(s));
  }
  const list = [...map.values()];
  for (const g of list) {
    g.years.sort((a, b) => a - b);
    g.topics = new Set(g.sections.map((s) => s.topic));
    g.search = [g.title, g.short, ...g.venues].join(' ').toLowerCase();
    g.bucket = g.years.length ? g.years[g.years.length - 1] : 'earlier';
  }
  return list;
}

function mountPapers(app, data) {
  const all = data.papers;
  const results = el('div');
  const venueCount = new Map();
  all.forEach((g) => g.venues.forEach((v) => venueCount.set(v, (venueCount.get(v) || 0) + 1)));
  const venues = [...venueCount].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const kinds = [...new Set(all.flatMap((g) => g.kinds))].sort();
  const yearList = all.flatMap((g) => g.years);
  const minY = Math.min(...yearList), maxY = Math.max(...yearList);

  const controls = el('div', { class: 'controls' },
    searchField('Search', 'q', 'Title, short name or venue', getParam('q'), (v) => { setParam('q', v); update(); }),
    selectField('Topic', 'topic', { all: 'All topics', items: TOPICS.map((t) => ({ value: t, label: t })) }, getParam('topic'), (v) => { setParam('topic', v); update(); }),
    selectField('Venue', 'venue', { all: 'All venues', items: venues.map(([v, n]) => ({ value: v, label: `${v} (${n})` })) }, getParam('venue'), (v) => { setParam('venue', v); update(); }),
    selectField('Type', 'type', { all: 'All types', items: kinds.map((k) => ({ value: k, label: k })) }, getParam('type'), (v) => { setParam('type', v); update(); }),
    selectField('Surveys', 'show', { all: 'Include surveys', items: [{ value: 'only', label: 'Surveys only' }, { value: 'hide', label: 'Hide surveys' }] }, getParam('show'), (v) => { setParam('show', v); update(); }));

  const match = (g, skipYear) => {
    const q = getParam('q').trim().toLowerCase();
    if (q && !g.search.includes(q)) return false;
    const topic = getParam('topic'); if (topic && !g.topics.has(topic)) return false;
    const venue = getParam('venue'); if (venue && !g.venues.includes(venue)) return false;
    const type = getParam('type'); if (type && !g.kinds.includes(type)) return false;
    const show = getParam('show'); if (show === 'only' && !g.survey) return false; if (show === 'hide' && g.survey) return false;
    const y = getParam('year');
    if (!skipYear && y && String(g.bucket) !== y && !g.years.map(String).includes(y)) return false;
    return true;
  };
  const filtersOn = () => ['q', 'topic', 'venue', 'type', 'show', 'year'].some((k) => getParam(k));

  function update() {
    const shown = all.filter((g) => match(g, false))
      .sort((a, b) => (typeof b.bucket === 'number' ? b.bucket : -1) - (typeof a.bucket === 'number' ? a.bucket : -1) || a.title.localeCompare(b.title));
    const base = all.filter((g) => match(g, true));
    const buckets = [];
    for (let y = minY; y <= maxY; y++) buckets.push({ value: y, label: String(y), count: base.filter((g) => g.years.includes(y)).length });
    buckets.unshift({ value: 'earlier', label: 'Earlier', count: base.filter((g) => g.bucket === 'earlier').length });

    results.replaceChildren(
      yearStrip(buckets, getParam('year'), 'papers', (v) => { setParam('year', v); update(); }),
      summaryLine([], shown.length, all.length, 'papers', filtersOn(), () => { ['q', 'topic', 'venue', 'type', 'show', 'year'].forEach((k) => setParam(k, '')); mountView(); }),
      shown.length ? el('ol', { class: 'list' }, shown.map(paperRow)) : el('p', { class: 'empty', text: 'No papers match these filters.' }));
  }
  app.replaceChildren(controls, results);
  update();
}

function paperRow(g) {
  const year = g.years.length ? (g.years.length > 1 ? `${g.years[0]}–${g.years[g.years.length - 1]}` : String(g.years[0])) : 'Earlier years';
  const meta = el('div', { class: 'meta' });
  if (g.venues.length) meta.append(el('span', { class: 'venue', text: g.venues.join(' / ') }));
  meta.append(el('span', { text: year }));
  if (g.short) meta.append(el('span', { class: 'short', text: g.short }));
  for (const s of g.sections) {
    meta.append(el('span', { class: `tag ${TOPIC_CLASS[s.topic] || ''}`, text: s.label }));
  }
  const labels = g.links.map((l) => link(l.label || 'Link', l.url));
  labels.forEach((a) => meta.append(a));
  const where = el('span', { class: 'src' }, 'README ');
  g.lines.forEach((n, i) => { if (i) where.append(' '); where.append(el('a', { href: srcUrl('README.md', n), rel: 'noopener noreferrer', title: 'Entry in the README', text: `line ${n}` })); });
  meta.append(where);
  return el('li', { class: 'paper' }, el('h2', { text: g.title }), meta);
}

// ---------------------------------------------------------------- datasets
const COLUMNS = [
  { key: 'year', label: 'Year', num: true, sort: true },
  { key: 'language', label: 'Language' },
  { key: 'samples', label: 'Samples' },
  { key: 'signers', label: 'Signers' },
  { key: 'domain', label: 'Domain' },
  { key: 'modality', label: 'Modality' },
  { key: 'available', label: 'Available' },
  { key: 'task', label: 'Task' },
];
const FIELD_LABELS = { samples: '#Samples', signers: '#Signers' };
const fieldLabel = (k) => FIELD_LABELS[k] || (k.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase()));
const CATEGORY = { fingerspelling: 'Fingerspelling', isolated: 'Isolated signs', continuous: 'Continuous signing' };

function availLabel(v) {
  const t = String(v ?? '').trim();
  if (isMissing(t)) return 'Not given';
  if (t === '✅' || t.startsWith('✅')) return 'Yes';
  if (t === '❌') return 'No';
  return t;
}

function mountDatasets(app, data) {
  const all = data.datasets;
  const results = el('div');
  const distinct = (fn) => [...new Set(all.flatMap(fn).filter((v) => v && !isMissing(v)))].sort((a, b) => a.localeCompare(b));
  const languages = distinct((d) => [d.fields.language]);
  const tasks = distinct((d) => d.fields.task.split(',').map((s) => s.trim()));
  const avails = [...new Set(all.map((d) => availLabel(d.fields.available)))].sort();
  const years = all.map((d) => num(d.fields.year)).filter((y) => y);
  const minY = Math.min(...years), maxY = Math.max(...years);
  const opts = (xs) => ({ items: xs.map((x) => ({ value: x, label: x })) });

  const controls = el('div', { class: 'controls' },
    searchField('Search', 'q', 'Name, language, domain or publication', getParam('q'), (v) => { setParam('q', v); update(); }),
    selectField('Kind', 'cat', { all: 'All kinds', items: Object.entries(CATEGORY).map(([value, label]) => ({ value, label })) }, getParam('cat'), (v) => { setParam('cat', v); update(); }),
    selectField('Language', 'lang', { all: 'All languages', ...opts(languages) }, getParam('lang'), (v) => { setParam('lang', v); update(); }),
    selectField('Task', 'task', { all: 'All tasks', ...opts(tasks) }, getParam('task'), (v) => { setParam('task', v); update(); }),
    selectField('Available', 'avail', { all: 'Any availability', ...opts(avails) }, getParam('avail'), (v) => { setParam('avail', v); update(); }));

  const match = (d, skipYear) => {
    const f = d.fields;
    const q = getParam('q').trim().toLowerCase();
    if (q && ![d.name, f.language, f.domain, f.publication].join(' ').toLowerCase().includes(q)) return false;
    if (getParam('cat') && d.category !== getParam('cat')) return false;
    if (getParam('lang') && f.language !== getParam('lang')) return false;
    if (getParam('task') && !f.task.split(',').map((s) => s.trim()).includes(getParam('task'))) return false;
    if (getParam('avail') && availLabel(f.available) !== getParam('avail')) return false;
    if (!skipYear && getParam('year') && String(num(f.year)) !== getParam('year')) return false;
    return true;
  };
  const keys = ['q', 'cat', 'lang', 'task', 'avail', 'year'];

  function update() {
    const sortKey = getParam('sort') || 'name', dir = getParam('dir') === 'desc' ? -1 : 1;
    const shown = all.filter((d) => match(d, false)).sort((a, b) => {
      const av = sortKey === 'year' ? num(a.fields.year) : a.name, bv = sortKey === 'year' ? num(b.fields.year) : b.name;
      if (av == null && bv == null) return 0; if (av == null) return 1; if (bv == null) return -1;
      return (typeof av === 'number' ? av - bv : av.localeCompare(bv)) * dir;
    });
    const base = all.filter((d) => match(d, true));
    const buckets = [];
    for (let y = minY; y <= maxY; y++) buckets.push({ value: y, label: String(y), count: base.filter((d) => num(d.fields.year) === y).length });
    results.replaceChildren(
      yearStrip(buckets, getParam('year'), 'datasets', (v) => { setParam('year', v); update(); }),
      summaryLine([], shown.length, all.length, 'datasets', keys.some(getParam), () => { keys.forEach((k) => setParam(k, '')); mountView(); }),
      shown.length ? datasetTable(shown, sortKey, dir, (k) => {
        setParam('dir', sortKey === k && dir === 1 ? 'desc' : 'asc'); setParam('sort', k); update();
      }) : el('p', { class: 'empty', text: 'No datasets match these filters.' }));
  }
  app.replaceChildren(controls, results);
  update();
}

function datasetTable(rows, sortKey, dir, onSort) {
  const th = (key, label, cls, sortable) => el('th', {
    scope: 'col', class: cls, 'aria-sort': sortKey === key ? (dir === 1 ? 'ascending' : 'descending') : null,
  }, sortable ? el('button', { type: 'button', onclick: () => onSort(key), text: label }) : label);
  const head = el('tr', {}, th('name', 'Dataset', '', true), ...COLUMNS.map((c) => th(c.key, c.label, c.num ? 'num' : '', c.sort)));
  const body = el('tbody');
  for (const d of rows) {
    const detail = el('tr', { class: 'detail', hidden: true }, el('td', { colspan: String(COLUMNS.length + 1) }, detailList(d)));
    const toggle = el('button', {
      type: 'button', class: 'link', 'aria-expanded': 'false',
      onclick: (e) => { const open = detail.hidden; detail.hidden = !open; e.currentTarget.setAttribute('aria-expanded', String(open)); },
      text: d.name,
    });
    const tr = el('tr', {}, el('td', { class: 'name' }, toggle, el('div', { class: 'dash', text: CATEGORY[d.category] || '' })));
    for (const c of COLUMNS) {
      const raw = d.fields[c.key];
      const cell = el('td', { class: c.num ? 'num' : '' });
      if (isMissing(raw)) cell.append(dash());
      else cell.append(c.key === 'available' ? el('span', { title: raw, text: availLabel(raw) }) : String(raw));
      tr.append(cell);
    }
    body.append(tr, detail);
  }
  return el('div', { class: 'tablewrap' }, el('table', {},
    el('caption', { text: 'Select a dataset name to see all of its fields.' }), el('thead', {}, head), body));
}

function detailList(d) {
  const dl = el('dl', { class: 'fields' });
  for (const [k, v] of Object.entries(d.fields)) {
    if (k === 'dataset') continue;
    const dd = el('dd');
    const urls = d.links[k] || [];
    if (isMissing(v)) dd.append(dash());
    else if (urls.length) dd.append(link(v, urls[0]));
    else dd.append(k === 'available' ? `${availLabel(v)} (${v})` : String(v));
    dl.append(el('dt', { text: fieldLabel(k) }), dd);
  }
  dl.append(el('dt', { text: 'Source' }), el('dd', {}, el('a', { href: srcUrl(d.source.file, d.source.line), rel: 'noopener noreferrer', text: `${d.source.file} line ${d.source.line}` })));
  return dl;
}

// ---------------------------------------------------------------- leaderboards
const NUMERIC = /^(year|wer|bleu|dtw|rouge|chrf|acc|top)/i;
function mountLeaderboards(app, data) {
  const rows = data.leaderboards;
  const tasks = [...new Set(rows.map((r) => r.task))];
  const task = tasks.includes(getParam('task')) ? getParam('task') : tasks[0];
  const dsList = [...new Set(rows.filter((r) => r.task === task).map((r) => r.dataset))];
  const ds = dsList.includes(getParam('ds')) ? getParam('ds') : dsList[0];
  const groups = [...new Set(rows.filter((r) => r.task === task && r.dataset === ds).map((r) => r.group || ''))];
  const grp = groups.includes(getParam('grp')) ? getParam('grp') : groups[0];

  const pick = (id, label, items, current, key, reset) => {
    const sel = el('select', { id });
    items.forEach((v) => sel.append(el('option', { value: v, text: v || 'Single table' })));
    sel.value = current;
    sel.addEventListener('change', () => { setParam(key, sel.value); reset.forEach((k) => setParam(k, '')); mountView(); });
    return field(label, id, sel);
  };
  const controls = el('div', { class: 'picker' },
    pick('task', 'Task', tasks, task, 'task', ['ds', 'grp']),
    pick('ds', 'Dataset', dsList, ds, 'ds', ['grp']),
    groups.length > 1 || groups[0] ? pick('grp', 'Setting', groups, grp, 'grp', []) : null);

  const sel = rows.filter((r) => r.task === task && r.dataset === ds && (r.group || '') === grp);
  const cols = sel[0].table_columns.slice(1);
  const head = el('tr', {}, el('th', { scope: 'col', class: 'rank', text: '#' }), el('th', { scope: 'col', text: 'Model' }),
    ...cols.map((c) => el('th', { scope: 'col', class: NUMERIC.test(c) ? 'num' : '', text: c })));
  const body = el('tbody');
  sel.forEach((r, i) => {
    const tr = el('tr', {}, el('td', { class: 'rank', text: String(i + 1) }),
      el('td', { class: 'name' }, r.model_url ? link(r.model, r.model_url) : r.model));
    if (r.column_mismatch) {
      tr.append(el('td', { colspan: String(cols.length) }, 'This row has an extra cell in the README, so its values are not shown here. ',
        el('a', { href: srcUrl('README.md', r.source.line), rel: 'noopener noreferrer', text: `README line ${r.source.line}` })));
    } else {
      for (const c of cols) {
        const v = r.fields[c];
        const td = el('td', { class: NUMERIC.test(c) ? 'num' : '' });
        if (isMissing(v)) td.append(dash());
        else if (c === 'Code' && r.code_url) td.append(link('Code', r.code_url));
        else td.append(String(v));
        tr.append(td);
      }
    }
    body.append(tr);
  });
  const title = [task, ds, grp].filter(Boolean).join(', ');
  app.replaceChildren(controls,
    el('p', { class: 'caution' }, 'Results are copied from the original papers and were not re-run. Training data, input modality and evaluation setup differ between rows, so compare with care. Rows follow the README order.'),
    el('div', { class: 'tablewrap' }, el('table', {}, el('caption', { text: `${title}: ${plural(sel.length, 'result', 'results')}` }), el('thead', {}, head), body)));
}

// ---------------------------------------------------------------- shell
let data;
function mountView() {
  const app = document.getElementById('app');
  document.querySelectorAll('#tabs a').forEach((a) => {
    if (a.dataset.view === view) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
  });
  document.title = `${view[0].toUpperCase() + view.slice(1)} | Open Sign Language`;
  ({ papers: mountPapers, datasets: mountDatasets, leaderboards: mountLeaderboards })[view](app, data);
}

function footer(meta, lint) {
  const foot = document.getElementById('foot');
  const src = meta.sources;
  const total = lint.counts.error + lint.counts.warn + lint.counts.info;
  foot.replaceChildren(
    el('p', {}, `Built from data/*.json, generated from README.md (sha256 ${src['README.md'].sha256.slice(0, 12)}) and helper/datasets.md (sha256 ${src['helper/datasets.md'].sha256.slice(0, 12)}). `,
      'Entries are shown as written in the repository, including mistakes; the topic of a paper is inferred from the README heading it sits under. Links written without https:// in the source are opened with https://.'),
    el('p', {}, `The data check reports ${plural(total, 'finding', 'findings')} in the sources: `, el('a', { href: '../docs/lint-report.md', text: 'lint report' }), '.'));
}

async function main() {
  try {
    const names = ['papers', 'datasets', 'leaderboards', 'meta', 'lint'];
    const got = await Promise.all(names.map((n) => fetch(`${DATA}${n}.json`).then((r) => { if (!r.ok) throw new Error(`${n}.json: HTTP ${r.status}`); return r.json(); })));
    data = { papers: buildPapers(got[0]), datasets: got[1], leaderboards: got[2] };
    footer(got[3], got[4]);
  } catch (err) {
    document.getElementById('app').replaceChildren(el('p', { class: 'notice' },
      `Could not load the data (${err.message}). Serve the repository root over HTTP, for example "python3 -m http.server" in the repository folder, and open /site/.`));
    return;
  }
  readHash();
  mountView();
  window.addEventListener('hashchange', () => { readHash(); mountView(); });
}
main();
